#!/usr/bin/env bash
# GTK theme - GTK2, GTK3 and GTK4, generated by KDE's own breeze-gtk from this theme's
# colour scheme, so the palette matches by construction rather than by hand.
#
#   gtk.sh --variant light              install the bundled prebuilt theme and point GTK at it
#   gtk.sh --variant light --rebuild    regenerate from the colour scheme installed on THIS host
#   gtk.sh --variant light --check      report what is installed and active, change nothing
#   gtk.sh --variant light --libadwaita also copy gtk-4.0/gtk.css into ~/.config/gtk-4.0 (see below)
#
# UNTESTED.
set -euo pipefail
. "$(dirname "$(readlink -f "$0")")/../lib/common.sh"
quantum_init "$@"; set -- "${QUANTUM_ARGS[@]+"${QUANTUM_ARGS[@]}"}"

DEST="$GTK_DEST"

if [[ "${1:-}" == "--check" ]]; then
  [[ -f "$DEST/gtk-3.0/gtk.css" ]] && say "installed: $DEST ($(find "$DEST" -type f | wc -l) files)" \
                                    || echo "    not installed: $DEST"
  for f in "$CONF/gtk-3.0/settings.ini" "$CONF/gtk-4.0/settings.ini" "$HOME/.gtkrc-2.0"; do
    [[ -f "$f" ]] && printf '    %-34s %s\n' "${f/#$HOME/~}" "$(grep -m1 -i 'gtk-theme-name' "$f" || echo '<no gtk-theme-name>')"
  done
  command -v gsettings >/dev/null && printf '    %-34s %s\n' "gsettings gtk-theme" "$(gsettings get org.gnome.desktop.interface gtk-theme 2>/dev/null)"
  command -v gsettings >/dev/null && printf '    %-34s %s\n' "gsettings color-scheme" "$(gsettings get org.gnome.desktop.interface color-scheme 2>/dev/null)"
  [[ -f "$CONF/gtk-4.0/gtk.css" ]] && say "libadwaita override present at ~/.config/gtk-4.0/gtk.css" || true
  exit 0
fi

# ---- get the theme into place ------------------------------------------------
if [[ "${1:-}" == "--rebuild" ]]; then
  # Regenerate from the scheme actually installed here. Correct if your Breeze differs
  # from the one the bundle was built against. Needs sassc and python3-cairo.
  command -v sassc >/dev/null || die "sassc not found: sudo apt install sassc"
  python3 -c 'import cairo' 2>/dev/null || die "python3-cairo not found: sudo apt install python3-cairo"
  [[ -f "$SCHEME_DEST" ]] || die "$SCHEME_DEST missing - run bin/colorscheme.sh --variant $SLUG first"
  TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
  say "cloning breeze-gtk"
  git clone --depth 1 -q https://invent.kde.org/plasma/breeze-gtk.git "$TMP/bg"
  sed 's|@Python3_EXECUTABLE@|python3|g' "$TMP/bg/src/build_theme.sh.cmake" > "$TMP/bg/src/build_theme.sh"
  chmod +x "$TMP/bg/src/build_theme.sh"
  # build_theme.sh needs the base scheme beside ours as its starting point
  mkdir -p "$TMP/schemes"
  cp "$SCHEME_DEST" "$TMP/schemes/"
  cp "$BASE_SCHEME_FILE" "$TMP/schemes/"
  say "rendering $ID from $SCHEME_DEST"
  ( cd "$TMP/bg/src" && ./build_theme.sh -c "$ID" -r "$TMP/schemes" -t "$DEST" )
else
  [[ -f "$GTK_BUNDLE" ]] || die "$GTK_BUNDLE missing"
  say "installing the prebuilt $ID theme to $DEST"
  rm -rf "$DEST"; mkdir -p "$DATA/themes"
  tar xzf "$GTK_BUNDLE" -C "$DATA/themes"
fi
say "$(find "$DEST" -type f | wc -l) files installed"

# ---- point GTK at it ---------------------------------------------------------
set_ini() {  # file, key, value
  local f="$1" k="$2" v="$3"
  mkdir -p "$(dirname "$f")"
  [[ -f "$f" ]] || printf '[Settings]\n' > "$f"
  grep -q '^\[Settings\]' "$f" || sed -i '1i [Settings]' "$f"
  if grep -q "^$k=" "$f"; then sed -i "s|^$k=.*|$k=$v|" "$f"; else sed -i "/^\[Settings\]/a $k=$v" "$f"; fi
}
say "writing GTK settings (prefer-dark-theme=$GTK_PREFER_DARK, portal=$PORTAL_PREF)"
for g in gtk-3.0 gtk-4.0; do
  set_ini "$CONF/$g/settings.ini" gtk-theme-name "$ID"
  set_ini "$CONF/$g/settings.ini" gtk-application-prefer-dark-theme "$GTK_PREFER_DARK"
done
if [[ -f "$HOME/.gtkrc-2.0" ]] && grep -q '^gtk-theme-name' "$HOME/.gtkrc-2.0"; then
  sed -i "s|^gtk-theme-name.*|gtk-theme-name=\"$ID\"|" "$HOME/.gtkrc-2.0"
else
  echo "gtk-theme-name=\"$ID\"" >> "$HOME/.gtkrc-2.0"
fi
if command -v gsettings >/dev/null; then
  gsettings set org.gnome.desktop.interface gtk-theme "$ID" 2>/dev/null || true
  gsettings set org.gnome.desktop.interface color-scheme "$PORTAL_PREF" 2>/dev/null || true
fi
XS="$CONF/xsettingsd/xsettingsd.conf"
if [[ -f "$XS" ]]; then
  grep -q '^Net/ThemeName' "$XS" && sed -i "s|^Net/ThemeName.*|Net/ThemeName \"$ID\"|" "$XS" \
                                 || echo "Net/ThemeName \"$ID\"" >> "$XS"
  pkill -HUP xsettingsd 2>/dev/null || true
fi

if [[ "${1:-}" == "--libadwaita" || "${2:-}" == "--libadwaita" ]]; then
  say "copying gtk-4.0/gtk.css to ~/.config/gtk-4.0 for libadwaita apps"
  mkdir -p "$CONF/gtk-4.0"
  cp "$DEST/gtk-4.0/gtk.css" "$CONF/gtk-4.0/gtk.css"
  cp -r "$DEST/assets" "$CONF/gtk-4.0/" 2>/dev/null || true
  warn "this overrides libadwaita globally. If a GTK4 app misrenders, delete"
  warn "~/.config/gtk-4.0/gtk.css and restart it."
fi

cat <<'MSG'

Two things worth knowing:

  * GTK4 apps built on libadwaita largely ignore themes. The bundled gtk-4.0 CSS helps
    plain GTK4 apps; for libadwaita ones, --libadwaita forces it, with the caveat above.
  * System Settings -> Colors -> Options: turn OFF "apply colors to non-Qt
    applications", or kde-gtk-config will fight this theme and win.

Already-running GTK apps need restarting.
MSG
